import{fileURLToPath}from"node:url";import{realpathSync}from"node:fs";import{contractPayloads,createContractServer}from"../repo/verifiers/contract_service.mjs";export{contractPayloads,createContractServer};function option(name,fallback){const index=process.argv.indexOf(`--${name}`);return index>=0?process.argv[index+1]:fallback;}if(process.argv[1]&&realpathSync(process.argv[1])===realpathSync(fileURLToPath(import.meta.url))){const host=option("host","127.0.0.1"),port=Number(option("port","4174"));createContractServer().listen(port,host,()=>console.log(`protected recovery service listening on http://${host}:${port}`));}
